#[cfg(test)]mod prefix_schedule_tests{
 use super::*;use crate::circuit::{analyze_ops,OperationType as K};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
 struct Words{bytes:Vec<u8>,at:usize}impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.copy_from_slice(&self.bytes[self.at..self.at+out.len()]);self.at+=out.len();}}
 fn circuit()->(Vec<crate::circuit::Op>,Vec<QubitId>,Vec<QubitId>,crate::circuit::BitId,u32){let mut c=Builder::new();let input=c.alloc_qubits(14);let guard=c.alloc_bit();c.push_condition(guard);let(held,peak)=c.r3_peak(|c|build(c,&input));c.pop_condition();assert_eq!(c.active_qubits(),34);assert_eq!(peak,41);let all:Vec<_>=input.iter().chain(&held).copied().collect();c.declare_qubit_register(&all);(c.take_ops(),input,held,guard,peak)}
 fn expected()->Vec<Vec<u64>>{let mut words=include_str!("prefix_schedule_expected.dat").split_whitespace().map(|x|x.parse::<u64>().unwrap());assert_eq!(words.next(),Some(34));assert_eq!(words.next(),Some(256));let rows=(0..34).map(|_|(0..256).map(|_|words.next().unwrap()).collect()).collect();assert!(words.next().is_none());rows}
 #[test]fn all16384_inputs_guards_and_independent_measurement_coefficients_match_native_prefix_functions(){
  let(ops,input,held,guard,_)=circuit();let(nq,nb,_,_)=analyze_ops(ops.iter());assert_eq!(nq,41);let draws=ops.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).count();assert_eq!(draws,11);assert_eq!(ops.iter().filter(|o|o.kind==K::CCX).count(),31);assert!(!ops.iter().any(|o|o.kind==K::CCZ));let exp=expected();
  for condition in[0,0xa55a_dd33_ff00_1701,u64::MAX]{for batch in 0..256{for mode in 0..15{let mut bytes=vec![0;draws*8];match mode{0=>{},1=>bytes.fill(255),2=>bytes.fill(0xa5),3=>{let mut h=Shake256::default();h.update(b"native-prefix27-independent-coefficients-v1");h.update(&(batch as u64).to_le_bytes());h.finalize_xof().read(&mut bytes);},i=>bytes[(i-4)*8..(i-3)*8].fill(255)}let mut rng=Words{bytes,at:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);for lane in 0..64{let value=batch*64+lane;for(i,&q)in input.iter().enumerate(){s.qubits[q.0 as usize]|=((value>>i&1)as u64)<<lane;}}let initial=s.qubits.clone();s.bits[guard.0 as usize]=condition;s.apply_iter(ops.iter());assert_eq!(s.phase,0,"batch{batch} mode{mode} guard{condition}");for(i,&q)in input.iter().enumerate(){assert_eq!(s.qubits[q.0 as usize],(exp[i][batch]&condition)|(initial[q.0 as usize]&!condition));}for(i,&q)in held.iter().enumerate(){assert_eq!(s.qubits[q.0 as usize],exp[14+i][batch]&condition);}for q in 0..nq as usize{if !input.iter().chain(&held).any(|w|w.0 as usize==q){assert_eq!(s.qubits[q],0);}}assert_eq!(s.stats.toffoli_gates,31*u64::from(condition.count_ones()));drop(s);assert_eq!(rng.at,draws*8);}}}
  eprintln!("NATIVE_PREFIX27 inputs16384 guards3 measurement_modes15 ANDs31 HMRs11 helper_peak27 final_helpers20 phase_clifford_only=1");
 }
 #[test]fn deleting_one_clifford_measurement_repair_is_detected(){let(mut ops,input,_,guard,_)=circuit();let at=ops.iter().position(|o|o.kind==K::CZ).unwrap();ops.remove(at);let(nq,nb,_,_)=analyze_ops(ops.iter());let mut caught=false;for batch in 0..256{let mut rng=Words{bytes:vec![255;11*8],at:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);for lane in 0..64{let value=batch*64+lane;for(i,&q)in input.iter().enumerate(){s.qubits[q.0 as usize]|=((value>>i&1)as u64)<<lane;}}s.bits[guard.0 as usize]=u64::MAX;s.apply_iter(ops.iter());caught|=s.phase!=0;}assert!(caught);}
}
